def join_path(self, *args):
    parts = []
    for arg in args:
        arg = self._unquote(arg).replace('/', '\\')
        if arg.startswith('\\\\'):
            # Add the UNC part directly to parts
            parts.append(arg)
        else:
            # Split and process the non-UNC parts
            parts.extend([a for a in arg.split('\\') if a])
    path = '\\'.join(parts)
    if path.startswith('~'):
        return path
    return path
